INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','easy','flashcard','What is the onset, peak, and duration of rapid-acting insulin analogues (lispro, aspart, glulisine)?','["Onset: 5-15 min | Peak: 30-90 min | Duration: 3-5 hours"]','A','Rapid-acting analogues were engineered to reduce self-aggregation in subcutaneous tissue, allowing faster absorption than regular human insulin. They should be given 0-15 minutes before meals and match prandial insulin needs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','easy','flashcard','What is the onset, peak, and duration of NPH insulin?','["Onset: 1-2 hours | Peak: 4-12 hours | Duration: 14-24 hours"]','A','NPH (Neutral Protamine Hagedorn) is an intermediate-acting insulin suspension. Its prolonged peak at 4-12 hours creates risk of nocturnal hypoglycaemia when given in the evening. It is the only insulin that can be mixed with regular or rapid-acting insulins in the same syringe.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','medium','flashcard','What is the pharmacokinetic profile of insulin glargine (Lantus/Toujeo) and why does it have no peak?','["Onset: 1-2 hours | No pronounced peak | Duration: ~24 hours. Mechanism: Glargine forms microprecipitates at physiological pH (pKa shift), dissolving slowly to release insulin monomers continuously."]','A','Glargine is formulated at pH 4 (soluble) but precipitates after injection into physiological pH 7.4 subcutaneous tissue. This creates a depot that slowly dissolves, providing a steady basal insulin level mimicking physiological overnight/fasting insulin secretion without a peak.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','medium','flashcard','Name 4 GLP-1 receptor agonists available clinically and state one key advantage of each.','["Exenatide (twice daily; first GLP-1 agonist), Liraglutide (once daily; CV benefit in LEADER), Semaglutide (once weekly; greatest weight loss; SELECT CV benefit), Dulaglutide (once weekly; REWIND CV benefit)"]','A','GLP-1 agonists all cause glucose-dependent insulin secretion, glucagon suppression, delayed gastric emptying, and weight loss. They differ primarily in duration of action, route, and degree of weight loss. All carry black-box warning for medullary thyroid carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','medium','flashcard','What is the unique pharmacological advantage of insulin degludec over glargine?','["Ultra-long duration >40 hours, lower nocturnal hypoglycaemia risk, and dosing flexibility (can be taken at different times each day if needed, maintaining at least 8h interval)"]','A','Degludec forms stable dihexamer chains in subcutaneous tissue that bind albumin, creating a circulating depot. Gradual release produces a flat PK profile over >40 hours. This provides more stable glucose levels and permits flexible dosing timing in patients with irregular schedules.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','hard','flashcard','State the FDA black-box warning for GLP-1 receptor agonists and which patients are excluded.','["Black-box warning: Risk of thyroid C-cell tumours (medullary thyroid carcinoma). Contraindicated in patients with personal or family history of medullary thyroid carcinoma or Multiple Endocrine Neoplasia type 2 (MEN2)."]','A','This warning is based on rodent carcinogenicity studies showing dose-dependent thyroid C-cell hyperplasia and tumours. Human causality has not been established but the warning is precautionary. Annual thyroid examination and monitoring for neck masses/dysphagia is recommended.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','easy','flashcard','What is the mechanism of action of pramlintide and when is it used?','["Pramlintide is a synthetic amylin analogue that suppresses postprandial glucagon, slows gastric emptying, and promotes satiety. Used as mealtime SC injection adjunct to insulin in type 1 and type 2 diabetes."]','A','Amylin is co-secreted with insulin from pancreatic beta-cells; it is deficient in diabetes. Pramlintide reduces postprandial glucose excursions without directly stimulating insulin. Main side effects: nausea, vomiting, and increased hypoglycaemia risk (requires insulin dose reduction at initiation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','hard','flashcard','Compare exenatide to liraglutide: frequency of injection, renal clearance considerations, and cardiovascular outcome data.','["Exenatide: twice daily (BID) or once weekly XR; renally cleared (avoid in eGFR <30); no CV mortality benefit (EXSCEL). Liraglutide: once daily; hepatically metabolised; 13% reduction in CV death in LEADER trial (T2DM with CV disease)."]','A','The LEADER trial established liraglutide as the first GLP-1 agonist with proven CV mortality reduction. Exenatide lacks this outcome benefit. Renal clearance of exenatide means it must be avoided in significant renal impairment, whereas liraglutides hepatic metabolism makes it safer in CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','medium','flashcard','What is the correct injection technique for insulin, and which sites have the fastest/slowest absorption?','["Inject subcutaneously into abdomen (fastest), thigh or buttock (slowest), or upper arm. Rotate sites within same region. Inject at 90 degrees (obese) or 45 degrees (lean). Avoid injecting into lipohypertrophic tissue."]','A','Lipohypertrophy from repeated injection into the same site impairs insulin absorption, causing unpredictable glucose levels. Abdomen provides most rapid and consistent absorption. Exercise over the injection site accelerates absorption. Insulin should be at room temperature before injection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Insulin & Injectable Antidiabetics','easy','flashcard','What are the symptoms of hypoglycaemia and at what glucose level do they typically occur?','["Autonomic (adrenergic) symptoms at ~3.5-3.8 mmol/L: sweating, tremor, palpitations, anxiety, hunger. Neuroglycopenic symptoms at ~2.8-3.0 mmol/L: confusion, slurred speech, seizure, loss of consciousness."]','A','Autonomic symptoms serve as the warning to prompt treatment. Patients with recurrent hypoglycaemia, long-standing diabetes, or autonomic neuropathy can develop hypoglycaemia unawareness — loss of autonomic warning symptoms, increasing seizure/coma risk. Continuous glucose monitoring (CGM) helps detect asymptomatic hypoglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','easy','flashcard','State 4 mechanisms by which metformin lowers blood glucose.','["1. Activates AMPK → reduces hepatic gluconeogenesis and glycogenolysis. 2. Improves peripheral insulin sensitivity (muscle). 3. Reduces intestinal glucose absorption. 4. Possibly improves gut microbiome composition favouring GLP-1 secretion."]','A','Metformins primary effect is hepatic: AMPK activation inhibits PEPCK and G6Pase enzymes, reducing new glucose synthesis. It does NOT stimulate insulin secretion, so hypoglycaemia as monotherapy is very rare. It is the first-line oral agent in type 2 diabetes worldwide (NICE, ADA guidelines).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','medium','flashcard','What are the contraindications to metformin and why?','["1. eGFR < 30 ml/min (risk of lactic acidosis from drug accumulation). 2. Active liver disease. 3. Excessive alcohol use. 4. Iodinated contrast media administration (withhold 48h peri-procedure in at-risk patients)."]','A','Metformin is renally cleared; accumulation in renal impairment increases plasma lactate, risking rare but potentially fatal metformin-associated lactic acidosis (MALA). Contrast media can cause acute nephrotoxicity, acutely reducing renal clearance of metformin. Restart 48 hours after contrast if renal function stable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','medium','flashcard','Compare sulfonylureas and DPP-4 inhibitors: mechanism, hypoglycaemia risk, and weight effect.','["Sulfonylureas (e.g., gliclazide): close K-ATP channels → insulin release regardless of glucose → hypoglycaemia risk YES → weight GAIN. DPP-4 inhibitors (e.g., sitagliptin): block DKK-4 degradation of GLP-1 → glucose-dependent insulin → hypoglycaemia risk LOW → weight NEUTRAL."]','A','Sulfonylureas bind the SUR1 subunit of beta-cell K-ATP channels in a glucose-independent manner. This is their main limitation. DPP-4 inhibitors amplify endogenous incretin effect without causing supra-physiological insulin levels, so hypoglycaemia is rare unless combined with insulin/SU. Gliptins are preferred in elderly patients at risk of hypoglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','hard','flashcard','List the cardiovascular and renal benefits of SGLT-2 inhibitors and which trials demonstrated them.','["CV benefits: empagliflozin reduced CV death/HF hospitalisation (EMPA-REG OUTCOME); canagliflozin reduced MACE (CANVAS). HF benefits: empagliflozin (EMPEROR-Reduced/Preserved), dapagliflozin (DAPA-HF). Renal benefits: canagliflozin slowed CKD progression (CREDENCE); dapagliflozin (DAPA-CKD)."]','A','SGLT-2 inhibitors have pleiotropic benefits beyond glycaemic control: haemodynamic (reduce preload/afterload via natriuresis), metabolic (reduce visceral fat, uric acid), and direct cardiac/renal tubular effects. They are now recommended for HFrEF and proteinuric CKD regardless of T2DM status.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','easy','flashcard','What are the GI side effects of metformin and how can they be minimised?','["Nausea, diarrhoea, abdominal discomfort, metallic taste. Minimise by: starting at low dose (500 mg once daily with food), titrating slowly over weeks, taking with meals, using extended-release formulation (MR/XR) which has better GI tolerability."]','A','GI side effects affect up to 30% of patients initiating metformin and are dose-dependent. They usually improve over time. Extended-release formulations (metformin MR) release drug slowly, reducing peak GI exposure and significantly improving tolerability, particularly for diarrhoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','medium','flashcard','What is euglycaemic diabetic ketoacidosis (euDKA) and which drug class causes it?','["EuDKA: Diabetic ketoacidosis with blood glucose typically < 14 mmol/L (not markedly elevated). Caused by SGLT-2 inhibitors via: reduced insulin secretion from glycosuria signal, increased glucagon:insulin ratio, and fatty acid oxidation to ketones."]','A','EuDKA can be missed because clinicians may not suspect DKA with near-normal glucose. Patients present with nausea, vomiting, abdominal pain, malaise, and dyspnoea. Blood ketones or urinary ketones must be checked in unwell patients on SGLT-2 inhibitors. Drug should be withheld perioperatively and during prolonged fasting.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','hard','flashcard','What is the mechanism of thiazolidinedione (pioglitazone) action and list 3 serious adverse effects?','["Mechanism: Activates PPAR-gamma (peroxisome proliferator-activated receptor-gamma) nuclear receptors in adipocytes and other tissues, increasing insulin sensitivity by redistributing fat from visceral to subcutaneous. Adverse effects: (1) Fluid retention/heart failure, (2) Increased bone fracture risk in women, (3) Possible bladder cancer with prolonged use."]','A','PPAR-gamma activation increases expression of GLUT-4 and other insulin-responsive genes. Pioglitazone has additional benefit on lipids (increases HDL, reduces triglycerides) and showed CV event reduction in PROactive trial. Contraindicated in NYHA III-IV HF. Bladder cancer risk led to withdrawal of rosiglitazone and restrictions on pioglitazone in some countries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','easy','flashcard','What monitoring is recommended for patients on long-term metformin (> 4 years)?','["Annual measurement of serum vitamin B12 levels. Also monitor eGFR annually (more frequently in CKD). Metformin reduces B12 absorption in 10-30% of long-term users, risking B12 deficiency anaemia and peripheral neuropathy."]','A','B12 deficiency on metformin is dose-dependent and increases with duration of use. It can masquerade as diabetic peripheral neuropathy or cause macrocytic anaemia. Oral B12 supplementation (1000 mcg daily) or 3-monthly IM hydroxocobalamin can be used for replacement. NICE recommends annual B12 monitoring in all patients on long-term metformin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','medium','flashcard','How do repaglinide and nateglinide (meglitinides) differ from sulfonylureas in their mechanism?','["Meglitinides also close K-ATP channels on beta-cells (same site as SUs) but bind reversibly and have very rapid onset and short duration. Taken with each meal ONLY - missed meals = skip dose. This reduces interprandial hypoglycaemia vs long-acting SUs."]','A','Meglitinides (glinides) are preferred in patients with irregular meal patterns. Their rapid in/rapid out pharmacokinetics mean they primarily control postprandial glucose, similar to rapid-acting insulin. Risk of hypoglycaemia is lower than long-acting sulfonylureas, but they share the same fundamental K-ATP channel mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Oral Antidiabetics','hard','flashcard','Name 3 SGLT-2 inhibitors, their specific licensed indications beyond T2DM glycaemic control, and one key adverse effect unique to each.','["Empagliflozin: HFrEF, HFpEF, CKD; specific: UTI/genital thrush. Dapagliflozin: HFrEF, HFpEF, CKD; specific: bladder cancer signal (weak). Canagliflozin: CKD (CREDENCE); specific: higher amputation risk (lower limb). All cause euglycaemic DKA."]','A','Each SGLT-2 inhibitor has a slightly different safety/efficacy profile. Canagliflozin showed a higher rate of lower limb amputations in the CANVAS trial (particularly first toe and metatarsal), though this was not reproduced in CREDENCE. Genital mycotic infections (thrush) occur in 5-10% of users due to glycosuria creating a glucose-rich environment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','easy','flashcard','State the 4 key management steps in DKA (the ABCDE framework specific to DKA).','["1. Fluids: 0.9% NaCl 1L in first hour, then replace deficit over 12-24h. 2. Insulin: fixed-rate IV insulin 0.1 units/kg/hr (start AFTER K+ confirmed > 3.5). 3. Potassium: replace according to serum K+ (add to IV fluid if K+ < 5.5). 4. Monitor: glucose hourly, ketones 2-hourly, electrolytes 2-4 hourly, pH."]','A','DKA resolution criteria: pH > 7.3, bicarbonate > 15 mmol/L, and ketones < 0.3 mmol/L. Blood glucose falling alone is NOT a criterion for DKA resolution. Add 5% dextrose when glucose < 14 mmol/L to continue insulin without causing hypoglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','medium','flashcard','What potassium replacement protocol is used in DKA and why is potassium monitoring critical?','["If K+ < 3.5: give K+ replacement BEFORE starting insulin. If K+ 3.5-5.5: add 40 mmol K+ to each litre of IV fluid. If K+ > 5.5: no K+ added but monitor hourly. Reason: insulin shifts K+ intracellularly, risking fatal hypokalaemia-induced VF without replacement."]','A','Initial serum K+ in DKA may be normal or high (acidosis causes K+ to exit cells in exchange for H+), but total body K+ is depleted from vomiting and osmotic diuresis. Insulin therapy rapidly reverses this, dropping serum K+. Untreated hypokalaemia during DKA is a major preventable cause of death.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','medium','flashcard','Describe the management of severe hypoglycaemia (unconscious patient, no IV access).','["IM glucagon 1 mg (adults) or 0.5 mg (child < 8 years / < 25 kg). Alternatively, intranasal glucagon 3 mg (Baqsimi). Once conscious, give oral carbohydrate. IV access: give 75-80 ml of 20% glucose IV (or 150 ml of 10% glucose)."]','A','Glucagon stimulates hepatic glycogenolysis and gluconeogenesis by activating glucagon receptors (Gs-coupled, increasing cAMP). It is ineffective in glycogen-depleted states (prolonged fasting, liver disease, heavy alcohol use). Glucagon kits should be available to all insulin-dependent diabetics and their carers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','hard','flashcard','How does HHS differ from DKA in pathophysiology, clinical features, and fluid management?','["HHS: Residual insulin prevents lipolysis/ketogenesis → no ketosis/acidosis. Glucose typically >30 mmol/L. Osmolality >320 mOsm/kg. Severe dehydration (8-10L deficit). Management: SLOW fluid replacement (0.9% NaCl) over 24-48h to avoid rapid osmolality fall causing cerebral oedema. Insulin started AFTER 1-2L fluid at 0.05 units/kg/hr (not 0.1)."]','A','HHS mortality (10-20%) exceeds DKA (<1%) due to older, frailer patients and severe thrombotic risk (VTE prophylaxis mandatory). Osmolality correction must be gradual: aim to reduce plasma osmolality by no more than 3-8 mOsm/kg/hr. Cerebral oedema is more common if correction is too rapid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','easy','flashcard','What is the immediate treatment of mild-to-moderate hypoglycaemia in a conscious patient?','["Rule of 15: Give 15-20g fast-acting carbohydrate (3-4 glucose tablets, 150 mL pure fruit juice, 5 jelly babies, 1 glass Lucozade). Recheck glucose after 15 minutes. Repeat if still < 4 mmol/L. Follow with starchy snack if next meal > 1 hour away."]','A','Avoid fat-containing foods (chocolate, biscuits) for immediate treatment as fat delays glucose absorption. Once hypoglycaemia is treated, identify the cause to prevent recurrence. If patient is on a sulfonylurea, monitor for 24-48 hours as hypoglycaemia can recur due to drugs prolonged action.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','medium','flashcard','Which electrolyte abnormalities must be monitored and corrected during DKA treatment?','["Potassium (K+): most critical — risk of fatal hypokalaemia with insulin. Phosphate: low after treatment but routine replacement not recommended unless severely low. Sodium: corrected sodium guides fluid choice. Magnesium: may be low but not routinely replaced unless symptomatic or arrhythmia."]','A','Corrected sodium in DKA = measured Na + 0.4 × (glucose - 5.5). High corrected Na suggests water deficit; use 0.45% NaCl. Phosphate falls with insulin (cellular uptake) and can worsen respiratory muscle weakness if very low, but routine phosphate infusion has not been shown to improve outcomes in DKA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','hard','flashcard','What is the role of bicarbonate therapy in DKA, and when (if ever) is it indicated?','["Sodium bicarbonate is NOT routinely recommended in DKA. Only consider if: pH < 6.9 with haemodynamic instability, severe hyperkalaemia causing ECG changes, or life-threatening acidosis. If given: 100 mL 8.4% NaHCO3 over 1 hour with additional 10 mmol KCl."]','A','Bicarbonate in DKA can cause paradoxical CSF acidosis, worsen hypokalaemia (H+/K+ exchange), impair oxygen delivery (leftward O2-Hb curve shift), and cause rebound alkalosis. Insulin and fluids correct acidosis physiologically by clearing ketones. The threshold for consideration is pH < 6.9 only.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','easy','flashcard','What defines DKA resolution and when can IV insulin be discontinued?','["DKA resolution: pH > 7.3 AND bicarbonate > 15 mmol/L AND blood ketones < 0.3 mmol/L (or urine ketones negative/trace). Before stopping IV insulin: give first SC dose of long-acting or intermediate insulin 30-60 minutes before stopping infusion."]','A','Blood glucose alone does not define DKA resolution. Continuing insulin until ketones are cleared is essential. The 30-60 minute overlap between first SC dose and stopping IV insulin allows time for subcutaneous insulin to be absorbed and prevents ketone rebound.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','medium','flashcard','How does octreotide help in sulfonylurea-induced refractory hypoglycaemia?','["Octreotide (somatostatin analogue) inhibits pancreatic insulin secretion via SSTR2/5 receptors on beta-cells. Dose: 50-100 mcg SC every 8 hours. Used when IV dextrose alone cannot maintain glucose despite repeated boluses, indicating ongoing sulfonylurea-driven insulin secretion."]','A','Sulfonylureas stimulate insulin release independently of glucose by binding SUR1 K-ATP channel subunit. Even high glucose concentrations may not overcome this. Octreotide directly suppresses beta-cell insulin secretion, addressing the root cause. IV dextrose treats the hypoglycaemia symptomatically; octreotide prevents continued insulin release.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Diabetic Emergencies','hard','flashcard','What is the Somogyi effect (rebound hyperglycaemia) and how does it differ from the Dawn phenomenon?','["Somogyi effect (debated): nocturnal hypoglycaemia triggers counter-regulatory hormone release (glucagon, cortisol, adrenaline) → rebound morning hyperglycaemia. Dawn phenomenon: physiological GH and cortisol release in early morning (3-8 AM) causes insulin resistance → morning hyperglycaemia WITHOUT preceding nocturnal hypoglycaemia."]','A','Management differs: Dawn phenomenon requires increasing basal insulin dose or switching to longer-acting insulin. Somogyi effect (if genuine) requires reducing evening insulin dose. CGM distinguishes them by showing whether glucose dips nocturnally. The Somogyi effects existence is controversial in modern literature.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','easy','flashcard','What is the mechanism of carbimazole and how long does it take to work?','["Carbimazole is a prodrug converted to methimazole. It inhibits thyroid peroxidase (TPO), blocking organification of iodide and synthesis of T3/T4. Clinical effect delayed 3-4 weeks because pre-formed thyroid hormone stores must deplete first."]','A','Carbimazole/methimazole do not block release of pre-formed T4/T3 from the thyroid. Beta-blockers (propranolol) are added in the interim to control symptoms (tachycardia, tremor, anxiety). The block-and-replace regimen maintains a consistent dose of carbimazole alongside levothyroxine to avoid hypothyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','medium','flashcard','Compare PTU vs carbimazole: mechanism differences, preferred use in pregnancy, and key side effects.','["PTU: Inhibits TPO AND blocks peripheral T4→T3 conversion (type 1 deiodinase). Use: First trimester pregnancy. Side effect: Hepatotoxicity (rare but fatal cases). Carbimazole: Inhibits TPO only. Use: Pre-conception, 2nd/3rd trimester. Side effect: Embryopathy (aplasia cutis, choanal atresia). Both: Risk of agranulocytosis."]','A','Switch from PTU to carbimazole at 12-14 weeks gestation: PTU preferred in T1 due to carbimazole teratogenicity; carbimazole preferred in T2/T3 due to PTU hepatotoxicity risk. Both drugs cross placenta. Both increase agranulocytosis risk (~0.3%). Patients must seek urgent FBC if sore throat/fever develops.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','medium','flashcard','List 4 drugs/classes used in thyroid storm and state each ones role.','["1. Propylthiouracil (PTU) high-dose: blocks new hormone synthesis AND T4→T3 conversion. 2. Lugols iodine (given 1 hour after PTU): blocks hormone release. 3. Propranolol high-dose: controls adrenergic symptoms AND inhibits T4→T3 conversion. 4. Hydrocortisone: prevents adrenal insufficiency, also inhibits T4→T3 conversion."]','A','Thyroid storm is a life-threatening emergency with mortality 10-20%. Additional management: IV fluid resuscitation, active cooling, treat precipitant (infection, surgery). Cholestyramine may be added to interrupt enterohepatic circulation of thyroid hormones. ICU admission is required. PTU is preferred over carbimazole for T4→T3 conversion blockade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','easy','flashcard','What are the counselling points for patients starting levothyroxine?','["Take on an empty stomach (30-60 min before breakfast). Avoid calcium, iron, antacids within 4 hours (chelate T4 reducing absorption). Start low dose (25-50 mcg) in elderly/cardiac disease. Titrate 4-6 weekly based on TSH. Once stable: annual TSH monitoring."]','A','Levothyroxine has a narrow therapeutic index; consistent timing and absorption are important. Starting dose for young healthy patients is 1.6 mcg/kg/day. In elderly, start 25-50 mcg to avoid precipitating cardiac arrhythmias. TSH normalises 6-8 weeks after dose change (reflects pituitary resetting to new T4 level).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','hard','flashcard','Describe the Wolff-Chaikoff effect and its escape mechanism.','["Wolff-Chaikoff effect: Acute high iodide load paradoxically inhibits TPO organification and thyroid hormone synthesis (elevated intrathyroid iodide inhibits NIS and TPO directly). Escape: Within 1-2 weeks, the thyroid downregulates NIS (sodium-iodide symporter), reducing iodide uptake, allowing organification to resume."]','A','Lugols iodine exploits the Wolff-Chaikoff effect pre-thyroidectomy (10 days): reduces gland vascularity, firmness, and hormone synthesis. In Graves disease, normal thyroid escape re-enables hormone synthesis after 2 weeks. In patients with dysfunctional thyroids (Hashimotos), escape may not occur, leading to permanent hypothyroidism from iodine excess (including amiodarone).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','medium','flashcard','What are the two types of amiodarone-induced thyrotoxicosis (AIT) and how do they differ?','["Type 1 AIT: Excess iodine (from amiodarone) drives new hormone synthesis in an abnormal thyroid (pre-existing nodular goitre/Graves). Treat with carbimazole/PTU. Type 2 AIT: Destructive thyroiditis releases pre-formed hormone from an otherwise normal thyroid. Treat with prednisolone (30-40 mg/day). Mixed type may require both."]','A','Distinguishing AIT types: vascularity on Doppler (high in type 1, low in type 2), thyroid scan (uptake in type 1, poor uptake in type 2), and IL-6 levels (elevated in type 2). Amiodarone should NOT be stopped immediately as half-life is 40-55 days and stopping may worsen the cardiac condition it was treating.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','easy','flashcard','What is the target TSH range during levothyroxine therapy for different patient groups?','["General population: TSH 0.4-4.0 mIU/L. Pregnancy: TSH 0.1-2.5 mIU/L (first trimester: < 2.5). Elderly (>70): TSH 1.0-6.0 mIU/L (slightly higher acceptable). Differentiated thyroid cancer post-thyroidectomy: TSH suppressed < 0.1 mIU/L (high-risk) or 0.1-0.5 mIU/L (low-risk)."]','A','In pregnancy, levothyroxine requirements increase by 25-50% from conception (especially weeks 4-12). Low TSH in early pregnancy stimulates thyroid via hCG cross-reactivity. Adequate maternal T4 is critical for fetal neurodevelopment in the first trimester before the fetal thyroid is functional.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','hard','flashcard','What is the thyroid peroxidase antibody (TPO-Ab) and what is its clinical significance?','["TPO antibodies are autoantibodies against thyroid peroxidase enzyme. Positive in: Hashimotos thyroiditis (90-95%) and Graves disease (70-80%). Clinical significance: Positive TPO-Ab in subclinical hypothyroidism (TSH 5-10) indicates 4x higher risk of progressing to overt hypothyroidism → treat with levothyroxine. Also: euthyroid women with TPO-Ab have higher risk of postpartum thyroiditis."]','A','TPO-Ab titre does not correlate with disease severity. It is the most sensitive marker for autoimmune thyroid disease. In pregnancy, TPO-Ab positive women should be monitored quarterly as they have 30-50% risk of postpartum thyroiditis. Selenium supplementation has modest evidence for reducing TPO-Ab titres in Hashimotos.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','medium','flashcard','What are the adverse effects of radioiodine (I-131) therapy?','["Short-term: Radiation thyroiditis (pain, tenderness, transient thyrotoxicosis exacerbation), parotitis, dry mouth. Long-term: Hypothyroidism (80% after 10 years — requires lifelong levothyroxine), small risk of exacerbating Graves ophthalmopathy. Contraindicated in: Pregnancy, breastfeeding, severe Graves ophthalmopathy."]','A','Post-I-131 patients must observe radiation safety precautions for 2 weeks (avoid prolonged close contact with pregnant women and children). Carbimazole is stopped 5-7 days pre-treatment to maximise I-131 uptake. If Graves ophthalmopathy is active, corticosteroid cover (prednisolone) is given peri-RAI to prevent worsening.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Thyroid Drugs','easy','flashcard','What are the symptoms and signs of hypothyroidism to recognise in clinical practice?','["Symptoms: fatigue, weight gain, cold intolerance, constipation, dry skin, hair loss, bradycardia, menorrhagia, depression, poor concentration. Signs: goitre (Hashimotos), periorbital puffiness, delayed relaxation of ankle reflexes, bradycardia, hyponatraemia."]','A','Slow relaxation of deep tendon reflexes (especially ankle) is a specific clinical sign of hypothyroidism. Hyponatraemia in hypothyroidism results from ADH excess (SIADH-like mechanism). Carpal tunnel syndrome is common due to glycosaminoglycan deposition. TSH is the single best screening test (sensitive early marker of thyroid dysfunction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','easy','flashcard','What are the sick day rules for patients with Addisons disease on hydrocortisone?','["DOUBLE the oral hydrocortisone dose for febrile illness (temperature > 37.5°C), vomiting, diarrhoea, or any moderate illness. INJECT hydrocortisone 100 mg IM if vomiting/unable to take oral medication. SEEK medical attention if no improvement in 24 hours (hospital for IV hydrocortisone)."]','A','All Addisons patients should carry a steroid emergency card and an emergency hydrocortisone injection kit (100 mg IM). Failure to increase corticosteroid during illness is the most common cause of Addisonian crisis. The doubling rule applies for mild-moderate illness; major surgery requires IV hydrocortisone stress dosing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','medium','flashcard','Describe the clinical features and immediate management of Addisonian crisis.','["Features: Severe hypotension, hypovolaemia, confusion, vomiting, abdominal pain, hypoglycaemia, hyponatraemia, hyperkalaemia. Management: IV hydrocortisone 100 mg stat + hourly thereafter. IV 0.9% NaCl 1L rapid resuscitation. IV dextrose for hypoglycaemia. Treat precipitant."]','A','Addisonian crisis is life-threatening (10% mortality if untreated). Do NOT delay hydrocortisone for investigation results. If unsure, give hydrocortisone empirically — the dose is safe for 24 hours. Fludrocortisone is not needed acutely as high-dose hydrocortisone has sufficient mineralocorticoid activity. Reduce to maintenance doses once stable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','medium','flashcard','What is Cushings syndrome and what are the main drug treatments?','["Cushings syndrome = cortisol excess. Drug causes: Long-term corticosteroid use (most common). Endogenous: pituitary ACTH-driven (Cushings disease). Drug treatments: (1) Metyrapone (11-beta-hydroxylase inhibitor), (2) Ketoconazole (CYP enzyme inhibitor), (3) Osilodrostat (newer 11-beta-hydroxylase inhibitor), (4) Pasireotide (SSTR agonist — Cushings disease), (5) Mifepristone (GR antagonist)."]','A','Medical therapy is second-line after surgery. Metyrapone is often used peri-operatively to control cortisol. Ketoconazole requires LFT monitoring. Osilodrostat (Isturisa) is newer and more selective for CYP11B1. All reduce cortisol and require careful titration to avoid adrenal insufficiency (over-correction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','hard','flashcard','What is the metyrapone test and what does it diagnose?','["The overnight metyrapone test: Give metyrapone 750 mg every 4 hours for 24 hours → measure plasma 11-deoxycortisol and cortisol the next morning. Normal response: 11-deoxycortisol rises > 200 nmol/L (confirms intact HPA axis). Blunted response = inadequate ACTH secretion (pituitary/hypothalamic failure) OR adrenal failure."]','A','Metyrapone blocks cortisol synthesis → cortisol falls → ACTH rises (normal HPA) → 11-deoxycortisol accumulates upstream of the block. In pituitary or hypothalamic hypofunction, ACTH cannot rise appropriately so 11-deoxycortisol remains low. The test is a dynamic HPA stress test assessing CRH-ACTH-adrenal axis integrity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','easy','flashcard','List 5 metabolic complications of long-term systemic glucocorticoid therapy.','["1. Hyperglycaemia/steroid diabetes. 2. Osteoporosis (inhibit osteoblasts, reduce calcium absorption). 3. Cushings syndrome features. 4. Hypertension (mineralocorticoid effect, increased angiotensinogen). 5. Hypokalaemia (mineralocorticoid effect on renal K+ excretion). Also: dyslipidaemia, weight gain, adrenal suppression."]','A','Preventative measures: co-prescribe bisphosphonate (+ calcium/vitamin D) for all patients on prednisolone >7.5 mg/day for > 3 months. Monitor blood pressure and glucose regularly. Use lowest effective dose and topical/inhaled routes where possible. Use steroid-sparing agents (azathioprine, methotrexate) to reduce steroid burden.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','medium','flashcard','What is the difference between primary and secondary adrenal insufficiency in terms of ACTH, aldosterone, and cortisol?','["Primary (Addisons): Adrenal gland failure → Low cortisol, Low aldosterone, HIGH ACTH (elevated due to loss of cortisol negative feedback). Secondary: Pituitary ACTH failure → Low cortisol, Normal aldosterone (RAAS intact), LOW ACTH. Both: Low cortisol and hypoglycaemia risk."]','A','Hyperpigmentation is ONLY seen in primary adrenal insufficiency (excess ACTH acts on melanocortin receptors). Aldosterone deficiency (primary only) causes hyponatraemia + hyperkalaemia + postural hypotension. Secondary adrenal insufficiency can present with isolated hyponatraemia (ADH excess without aldosterone deficiency). Fludrocortisone is NOT needed in secondary AI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','hard','flashcard','Describe the mechanism of pasireotide and why it causes hyperglycaemia.','["Pasireotide binds SSTR1, 2, 3, and 5 (highest SSTR5 affinity). Suppresses ACTH from corticotroph adenoma → reduces cortisol. Causes hyperglycaemia by: (1) SSTR5 activation inhibits insulin secretion from beta-cells, (2) SSTR5 inhibits GLP-1 and GIP incretin secretion from gut. Effect: glucose rises despite cortisol falling."]','A','Hyperglycaemia occurs in ~73% of patients on pasireotide in Cushings disease. Unlike other Cushings treatments where glycaemia improves with cortisol reduction, pasireotide worsens it. Management: GLP-1 agonists or DPP-4 inhibitors are preferred for drug-induced hyperglycaemia as they work on the same downstream GLP-1/GIP pathway inhibited by pasireotide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','easy','flashcard','What are the side effects of fludrocortisone (mineralocorticoid excess)?','["Hypertension, oedema, hypokalaemia, and headache from sodium and water retention. Dose is too high if: BP rises, oedema develops, or K+ falls. Monitor: blood pressure, serum electrolytes, weight. Standard adult dose: 50-200 mcg once daily."]','A','Fludrocortisone dose is titrated to blood pressure (target normotension), absence of postural hypotension, and normal serum potassium. During pregnancy, requirements often increase. In hot weather or high sodium intake, dose may need reduction. Potassium supplements may be needed if K+ falls below 3.5 mmol/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','medium','flashcard','What is the Short Synacthen Test (SST) and what does it test?','["Give 250 mcg synthetic ACTH (tetracosactide) IV/IM. Measure cortisol at 0 and 30 minutes. Adequate response (normal adrenal function): cortisol > 450 nmol/L at 30 minutes. Fail = adrenal insufficiency. Tests adrenal cortex ability to respond to maximal ACTH stimulation."]','A','SST detects primary adrenal insufficiency reliably. It can miss secondary (pituitary) adrenal insufficiency in acute hypopituitarism (<4 weeks) because the adrenal gland has not yet atrophied. In early secondary AI, insulin tolerance test (ITT) or glucagon stimulation test is more sensitive. SST is contraindicated in myocardial infarction and epilepsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Adrenal Drugs','hard','flashcard','Compare ketoconazole, metyrapone, and mitotane as treatments for Cushings syndrome.','["Ketoconazole: Multiple CYP enzyme inhibitor; oral; hepatotoxic (LFT monitoring); adrenal steroidogenesis inhibitor. Metyrapone: Selective 11-beta-hydroxylase inhibitor; rapid onset; hirsutism/acne from androgen build-up; used perioperatively. Mitotane: Adrenolytic + CYP inhibitor; used in adrenocortical carcinoma; requires replacement glucocorticoid (destroys adrenal tissue); neurotoxic at high doses."]','A','Mitotane is the only adrenolytic drug — it permanently destroys adrenocortical tissue. All patients on mitotane need lifelong glucocorticoid replacement. Drug monitoring of mitotane plasma levels (target 14-20 mg/L) is required to balance efficacy vs neurological toxicity. Osilodrostat and levoketoconazole are newer, more selective adrenal steroidogenesis inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','easy','flashcard','What are the bisphosphonates and how do they reduce fracture risk?','["Alendronate, risedronate, ibandronate (oral); zoledronic acid (IV annually). Mechanism: Inhibit osteoclast farnesyl pyrophosphate synthase → osteoclast apoptosis → reduced bone resorption → increased BMD. Reduce vertebral fractures 40-70%, hip fractures 30-50%."]','A','Bisphosphonates incorporate into bone matrix and are released when osteoclasts acidify the resorption pit, delivering the drug intracellularly. This means effects persist for months after stopping. Duration of treatment: typically 5 years oral or 3 years IV (zoledronic acid), then reassess (consider drug holiday in low-moderate risk).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','medium','flashcard','What is the pathophysiology of bisphosphonate-related osteonecrosis of the jaw (BRONJ)?','["Bisphosphonates concentrate in jaw bone (high bone turnover). After dental procedures or trauma, osteoclast suppression prevents normal bone remodelling and healing. Exposed, avascular bone fails to heal → BRONJ. Risk factors: IV bisphosphonates (cancer doses), poor dental hygiene, dental extractions, steroids."]','A','Risk is much higher with IV bisphosphonates (used in cancer at 10-50x osteoporosis doses) than with oral weekly osteoporosis doses. Prevention: dental review and treatment before starting IV bisphosphonates; avoid dental extractions if possible; maintain excellent oral hygiene. Management: chlorhexidine mouth rinses, antibiotics, surgery in severe cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','medium','flashcard','Compare teriparatide and bisphosphonates: mechanism, route, and who benefits most.','["Teriparatide (PTH 1-34): Anabolic — stimulates new bone formation → increases cortical and trabecular bone. SC daily injection. Duration: max 24 months (osteosarcoma risk in animals). Best for: Severe osteoporosis (T-score < -3.5), multiple vertebral fractures, failure of bisphosphonates. Bisphosphonates: Anti-resorptive, oral/IV, long-term use."]','A','After teriparatide, transition to bisphosphonate or denosumab is essential. Without anti-resorptive therapy post-teriparatide, rapid bone loss occurs within 12 months. Teriparatide increases bone formation markers (P1NP) — measured to monitor response. Cost limits use to severe osteoporosis in most healthcare systems.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','hard','flashcard','Explain the mechanism of cinacalcet (calcimimetic) and how it differs from vitamin D analogues in treating secondary hyperparathyroidism in CKD.','["Cinacalcet: Positive allosteric modulator of CaSR (calcium-sensing receptor) on parathyroid chief cells → increases CaSR sensitivity to Ca2+ → suppresses PTH WITHOUT raising serum Ca2+ or phosphate. Vitamin D analogues (calcitriol/alfacalcidol): Directly suppress PTH transcription but raise Ca2+ and phosphate → hypercalcaemia/hyperphosphataemia risk."]','A','In CKD, secondary hyperparathyroidism (high PTH) causes renal osteodystrophy and cardiovascular calcification. Cinacalcet avoids hypercalcaemia and may reduce the Ca × phosphate product, which is important for preventing vascular calcification. It can cause hypocalcaemia (measure serum Ca before each dose change). The EVOLVE trial evaluated cinacalcet outcomes in dialysis patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','easy','flashcard','What are the correct administration instructions for oral bisphosphonates?','["Take on a completely empty stomach first thing in the morning. Swallow with at least 200 mL of plain water ONLY (no juice, coffee, milk). Remain sitting or standing upright for at least 30 minutes. Do not eat, drink, or take other medications for 30-60 minutes."]','A','These instructions minimise oesophageal irritation and maximise absorption (only 0.5-1% is absorbed even in ideal conditions). Taking with food reduces absorption by >60%. If the patient forgets the weekly dose, take it the next morning but do not take 2 doses in 1 week. Ibandronate monthly and zoledronic acid annually improve adherence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','medium','flashcard','What is the role of denosumab in osteoporosis and what unique consideration applies when stopping it?','["Denosumab (Prolia): RANKL antibody, SC every 6 months. Reduces vertebral fractures by 68% (FREEDOM trial). Unique risk: RAPID bone loss on discontinuation (rebound increase in bone turnover) → multiple vertebral fractures within 12 months. Transition to bisphosphonate is MANDATORY when stopping denosumab."]','A','Unlike bisphosphonates (which persist in bone matrix), denosumabs effect is entirely reversible when cleared. RANKL rebounds → osteoclasts reactivate → rapid bone resorption above pre-treatment baseline. Multiple spontaneous vertebral fractures have been reported after stopping denosumab without transition therapy. This is now a critical safety warning.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','hard','flashcard','Describe the mechanism of romosozumab and its cardiovascular safety concern.','["Romosozumab (Evenity): Anti-sclerostin monoclonal antibody. Sclerostin (from osteocytes) inhibits Wnt/beta-catenin signalling, suppressing osteoblasts. Inhibiting sclerostin → osteoblast activation (anabolic) + reduced RANKL expression (anti-resorptive). Dual mechanism = fastest bone density gains. CV concern: ARCH trial showed increased serious cardiovascular events vs alendronate."]','A','Romosozumab is given monthly SC for 12 months only. The ARCH trial (high CV risk patients) showed increased MI and stroke vs alendronate. Romosozumab is therefore contraindicated in patients with recent MI or stroke. The FRAME trial (lower CV risk) showed no CV signal vs placebo. It is indicated for severe osteoporosis in postmenopausal women at high fracture risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','easy','flashcard','What calcium and vitamin D supplementation is recommended for adults on bisphosphonate therapy?','["Calcium: 1000-1200 mg/day total (dietary + supplements). Vitamin D: 800-2000 IU (20-50 mcg) cholecalciferol daily. Target serum 25-OH vitamin D: > 50 nmol/L. Take calcium supplements at least 2 hours apart from bisphosphonate (chelation reduces bisphosphonate absorption)."]','A','Adequate vitamin D and calcium are prerequisites for bisphosphonate efficacy. Vitamin D deficiency should be corrected before starting bisphosphonates (risk of bisphosphonate-induced hypocalcaemia and symptomatic tetany in deficient patients). Routine calcium supplementation without deficiency in older adults may carry cardiovascular risk; dietary calcium is preferable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','medium','flashcard','What is the clinical significance of the FRAX score in osteoporosis management?','["FRAX (Fracture Risk Assessment Tool) calculates the 10-year probability of major osteoporotic fracture and hip fracture based on: age, sex, BMI, femoral neck T-score, prior fractures, parental hip fracture, smoking, alcohol, glucocorticoid use, rheumatoid arthritis, secondary osteoporosis. Used to guide treatment thresholds for bisphosphonate initiation."]','A','FRAX allows risk stratification without DXA in some settings. NICE thresholds (UK): treat if 10-year risk exceeds age-appropriate threshold on NOGG charts. Limitations: FRAX underestimates risk in recent fractures and does not account for fall risk, number of falls, or fracture severity. Updated with lumbar spine T-score in some algorithms (FRAX+LS).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Calcium & Bone Drugs','easy','flashcard','What is osteoporosis and what T-score defines it by WHO criteria?','["Osteoporosis defined by WHO as bone mineral density (BMD) T-score <= -2.5 on DXA scan (compared to young adult mean). Osteopenia: T-score -1.0 to -2.5. Normal: T-score > -1.0. Osteoporosis is characterised by reduced bone mass and microarchitectural deterioration increasing fracture risk."]','A','The T-score compares patient BMD to peak bone mass of young adults. For clinical decisions, the FRAX tool integrates T-score with clinical risk factors to estimate 10-year fracture probability. Major fracture sites: vertebral, hip, wrist (Colles fracture), proximal humerus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','easy','flashcard','What are the first-line treatment options for prolactinoma?','["Dopamine agonists are first-line for all prolactinomas (except when vision threatened requiring emergency surgery). Cabergoline (preferred): once or twice weekly, normalises prolactin in 80-90%, shrinks tumour. Bromocriptine: daily-TDS, more side effects, less effective. Surgery (transsphenoidal) if dopamine agonist intolerance/resistance."]','A','Cabergoline is preferred because: longer half-life (65 hours), better tolerability (less nausea/vomiting), once-twice weekly dosing improving adherence, and superior efficacy. Unlike surgery/radiotherapy, dopamine agonists can be withdrawn after 2+ years of sustained normal prolactin and > 50% tumour shrinkage, with approximately 30% maintaining remission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','medium','flashcard','What is acromegaly and what are the pharmacological treatment options?','["Acromegaly: GH-secreting pituitary adenoma → chronic GH and IGF-1 excess → soft tissue overgrowth, visceromegaly, glucose intolerance, CV disease, arthropathy. Pharmacological options: (1) Somatostatin analogues (octreotide/lanreotide LAR), (2) Pegvisomant (GH receptor antagonist), (3) Dopamine agonists (cabergoline — mild cases), (4) Combination therapy."]','A','First-line treatment is transsphenoidal surgery. Medical therapy is for post-operative residual disease, surgical contraindication, or patient preference. Somatostatin analogues normalise GH/IGF-1 in 40-60% and reduce tumour volume in 30-50%. Pegvisomant normalises IGF-1 in >90% but does not reduce tumour size. Monitoring: IGF-1 (not GH, which rises on pegvisomant).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','medium','flashcard','Explain the therapeutic principle of GnRH agonist (leuprorelin) pulsatile vs continuous administration.','["Pulsatile GnRH (physiological): stimulates LH/FSH → gonadotrophin secretion → sex hormone production (used in hypothalamic hypogonadism). Continuous GnRH agonist: receptor downregulation → paradoxical suppression of LH/FSH → sex hormone suppression (used in: prostate cancer, endometriosis, precocious puberty, IVF downregulation, gender-affirming therapy)."]','A','GnRH receptors (Gq-coupled) require intermittent stimulation (pulsatile every 90 minutes) for sustained LH/FSH secretion. Continuous exposure uncouples the receptor from Gq signalling (desensitisation) and promotes receptor internalisation (downregulation). The initial 2-week testosterone flare with GnRH agonists in prostate cancer is managed with anti-androgen (bicalutamide) co-prescription.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','easy','flashcard','What is central diabetes insipidus and how is desmopressin used to treat it?','["Central DI: Deficiency of ADH (vasopressin) from posterior pituitary. Symptoms: Polydipsia, massive polyuria (urine output > 3L/day), dilute urine (osmolality < 300 mOsm/kg), normal or high serum osmolality. Treatment: Desmopressin — intranasal, sublingual, or oral. Acts on renal V2 receptors to concentrate urine."]','A','Distinguish central DI from nephrogenic DI (ADH present but kidney unresponsive) with water deprivation test + desmopressin challenge: central DI responds with urine concentration; nephrogenic DI does not. Desmopressin dose for DI: intranasal 10-40 mcg/day or oral 100-800 mcg/day. Monitor for hyponatraemia (risk of excess water retention if over-treated).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','hard','flashcard','What is the role of pegvisomant in acromegaly and why does IGF-1 (not GH) guide dosing?','["Pegvisomant competitively blocks GH receptors (GHR), preventing JAK2-STAT5 signalling. Blocking GHR prevents hepatic IGF-1 synthesis. GH rises compensatorily (loss of IGF-1 negative feedback). Therefore: GH levels cannot be used to monitor response (they rise). IGF-1 normalises in >90% — this is the treatment monitoring biomarker."]','A','Pegvisomant is used as monotherapy or combined with somatostatin analogues for acromegaly resistant to or poorly controlled by SSA therapy. It does not reduce tumour size (requires MRI monitoring). Starting dose 10 mg/day SC, titrated to IGF-1. Liver enzyme elevation (aminotransferases) occurs in 3-5% — LFTs must be monitored regularly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','medium','flashcard','What is the mechanism and use of octreotide/lanreotide in carcinoid syndrome?','["Somatostatin analogues (octreotide, lanreotide) bind SSTR2 (predominantly expressed on carcinoid tumour cells) → inhibit serotonin and other vasoactive peptide secretion from the tumour → relieve carcinoid syndrome (flushing, diarrhoea, bronchospasm). Also have antiproliferative effect (PROMID trial: lanreotide improved PFS in NETs)."]','A','Carcinoid crisis can occur during surgery, anaesthesia, or tumour biopsy. Prophylactic octreotide infusion perioperatively prevents life-threatening serotonin release. Urine 5-HIAA (5-hydroxyindoleacetic acid) is the monitoring biomarker for carcinoid syndrome treatment response. Lanreotide Autogel monthly injections have replaced subcutaneous octreotide TDS in most patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','easy','flashcard','What are the common side effects of somatostatin analogues (octreotide/lanreotide)?','["GI: nausea, diarrhoea, steatorrhoea, flatulence (from inhibited pancreatic enzyme/acid secretion). Gallstones: occurs in 20-30% of patients (reduced gallbladder motility and bile salt changes). Glucose: hyperglycaemia OR hypoglycaemia (insulin/glucagon both suppressed). Injection site reactions with depot formulations."]','A','Gallstones are the most important long-term side effect, occurring in up to 30% of patients. Most are asymptomatic. Ursodeoxycholic acid prophylaxis is sometimes used. Baseline and annual ultrasound monitoring is recommended. Glucose should be monitored on initiation as both insulin and glucagon are suppressed, with unpredictable net glucose effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','hard','flashcard','Describe the water deprivation test protocol and how results distinguish central DI, nephrogenic DI, and SIADH.','["Protocol: Fluid deprivation until urine osmolality plateaus (< 30 mOsm/kg rise over 1 hour) or until 3% body weight lost. Give desmopressin 2 mcg IM. Measure urine osmolality 1-2 hours post-desmopressin. Results: Central DI: Urine osmolality rises >50% after desmopressin. Nephrogenic DI: Minimal response. SIADH: Inappropriately concentrated urine throughout (diagnosis by other criteria)."]','A','Close patient supervision during water deprivation is essential (hypernatraemia risk). Stop if serum sodium > 150 mmol/L or osmolality > 305 mOsm/kg. Partial central DI shows intermediate response. Prolonged water deprivation before desmopressin allows sufficient dehydration to maximally stimulate endogenous ADH and test the kidneys concentrating capacity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','medium','flashcard','What is tolvaptan (Samsca/Jynarque) and what are its two main clinical uses?','["Tolvaptan is a vasopressin V2 receptor antagonist. Uses: (1) SIADH/hypervolaemic/euvolaemic hyponatraemia — corrects sodium by aquaresis (electrolyte-sparing free water excretion). (2) Autosomal dominant polycystic kidney disease (ADPKD) — slows renal cyst growth by blocking vasopressin-driven cAMP in tubular cells. Warning: hepatotoxicity (FDA black box for ADPKD)."]','A','Correction of hyponatraemia with tolvaptan must be controlled: do not exceed 8-10 mmol/L per 24 hours (12 mmol maximum) to prevent osmotic demyelination syndrome (ODS). Patients should be hospitalised for initiation; "free fluid" access should be allowed. Avoid in patients who cannot perceive thirst or access water independently.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Pituitary Drugs','easy','flashcard','What is central diabetes insipidus and list 4 common causes?','["Central (cranial) DI: ADH deficiency from posterior pituitary or hypothalamus. Causes: (1) Idiopathic/autoimmune (30%), (2) Pituitary surgery/trauma, (3) Craniopharyngioma, (4) Head injury, infiltrative disease (sarcoidosis), or malignancy metastases. Presents with polyuria > 3L/day, polydipsia, and dilute urine (osmolality < 300 mOsm/kg)."]','A','Pituitary surgery is the leading acquired cause. Biphasic DI can occur post-pituitary surgery: immediate DI (damaged axons) followed by SIADH (dying neurons release ADH), then permanent DI if >90% of neurons lost. Desmopressin must be withheld during the SIADH phase to avoid dangerous hyponatraemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','easy','flashcard','What is the anti-inflammatory potency and mineralocorticoid activity of key corticosteroids (relative to hydrocortisone = 1)?','["Hydrocortisone: anti-inflam 1, mineralocorticoid 1 (20mg equivalent). Prednisolone: anti-inflam 4, mineralocorticoid 0.8 (5mg). Methylprednisolone: anti-inflam 5, mineralocorticoid 0.5 (4mg). Dexamethasone: anti-inflam 25-30, mineralocorticoid ~0 (0.75mg). Fludrocortisone: anti-inflam 10, mineralocorticoid 125."]','A','These equivalences are used clinically for dose conversion and route switching. Dexamethasones negligible mineralocorticoid activity makes it ideal for brain oedema (no sodium/water retention), croup, and antenatal lung maturation. Fludrocortisones extreme mineralocorticoid:glucocorticoid ratio makes it used only for mineralocorticoid replacement (Addisons, CAH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','medium','flashcard','Describe the molecular mechanism by which glucocorticoids inhibit inflammation.','["GC binds cytosolic GR → GR:GC complex translocates to nucleus → Transactivation: induces lipocortin-1 (blocks PLA2, reducing arachidonic acid), IkB-alpha (blocks NF-kB), GILZ (anti-inflammatory). Transrepression: directly inhibits AP-1 and NF-kB → suppresses IL-1, IL-6, TNF-alpha, COX-2 gene transcription."]','A','Transrepression (blocking NF-kB/AP-1) is primarily responsible for anti-inflammatory effects. Transactivation (inducing lipocortin-1, GR-responsive genes) contributes to anti-inflammation but also to metabolic side effects (gluconeogenesis genes, PEPCK induction). Dissociated corticosteroids that transrepress without transactivating are being developed to separate efficacy from side effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','medium','flashcard','List 10 important side effects of long-term systemic corticosteroid therapy.','["Metabolic: hyperglycaemia, weight gain (central obesity), dyslipidaemia. Musculoskeletal: osteoporosis, proximal myopathy, avascular necrosis of femoral head. Skin: striae, easy bruising, thin skin, impaired wound healing. Eyes: posterior subcapsular cataracts, glaucoma. Adrenal: HPA suppression. Immune: immunosuppression, susceptibility to infections. CNS: mood changes, insomnia, psychosis."]','A','Preventative strategies: Use minimum effective dose; use topical/inhaled routes where possible; co-prescribe bisphosphonate (+ calcium/vitamin D) for osteoporosis prevention from day 1 of treatment expected >3 months at >7.5 mg prednisolone equivalent; monitor blood pressure, glucose, weight, and ophthalmological assessment annually.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','easy','flashcard','What is the HPA (hypothalamic-pituitary-adrenal) axis and how do exogenous glucocorticoids suppress it?','["HPA axis: Hypothalamus → CRH → Pituitary → ACTH → Adrenal cortex → Cortisol → negative feedback to hypothalamus and pituitary. Exogenous GCs: mimic cortisol, providing strong negative feedback → CRH and ACTH secretion suppressed → adrenal glands become atrophic → cannot produce endogenous cortisol when drug stopped."]','A','Degree of HPA suppression depends on dose, duration, timing of administration, and potency of corticosteroid. Alternate-day dosing causes less HPA suppression. Morning dosing (mimicking natural diurnal pattern) also reduces suppression. After >3 weeks of treatment, assume HPA suppression and taper. Short burst (<3 weeks) can generally be stopped without tapering.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','hard','flashcard','How is corticosteroid-induced osteoporosis prevented and treated according to NICE/ACR guidelines?','["Prevention: All patients starting prednisolone >7.5 mg/day for >3 months → prescribe alendronate 70 mg weekly + calcium 1000 mg/day + vitamin D 800 IU/day. If age < 40 and female: assess DXA first. Treatment of established GIO: bisphosphonate; if severe fractures/bisphosphonate failure: teriparatide (most evidence in GIO)."]','A','GIOP (glucocorticoid-induced osteoporosis) is the leading cause of secondary osteoporosis. FRAX with glucocorticoid correction (multiply FRAX score by 1.15 for prednisolone > 7.5 mg) estimates fracture risk. Teriparatide has the strongest evidence for vertebral fracture prevention in GIO, with superiority shown over alendronate in the PaTH trial.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','medium','flashcard','What are inhaled corticosteroids (ICS) used for and list 3 key local side effects?','["Used for: Persistent asthma (long-term controller), COPD (combined with LABA in moderate-severe disease), eosinophilic oesophagitis. Local side effects: (1) Oral candidiasis (oropharyngeal thrush), (2) Dysphonia (hoarse voice from laryngeal muscle weakness), (3) Cough. Prevention: Use spacer device, rinse mouth with water after each use."]','A','ICS are the cornerstone of asthma control. Step up before adding LABA. High-dose ICS (fluticasone > 500 mcg/day, budesonide > 800 mcg/day) carry systemic risk including adrenal suppression (particularly in children), growth suppression in children, and osteoporosis with prolonged high-dose use. Spacer reduces oropharyngeal deposition significantly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','easy','flashcard','In the management of severe anaphylaxis, what is the role of hydrocortisone?','["Hydrocortisone 200 mg IV (or methylprednisolone 125 mg IV) is given as second-line in anaphylaxis AFTER adrenaline (epinephrine). Role: Prevents biphasic anaphylaxis (delayed recurrence 6-12 hours later), has onset over hours (NOT immediate). Adrenaline (IM, anterolateral thigh) remains the ONLY life-saving immediate treatment."]','A','Hydrocortisone in anaphylaxis does NOT act quickly enough to treat acute anaphylaxis (genomic mechanism requires hours). Its value is in reducing the risk of biphasic reaction. All patients with anaphylaxis should be observed for 6-12 hours post-anaphylaxis. Antihistamines (chlorphenamine) treat urticaria/itch but have NO role in treating cardiovascular collapse.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','hard','flashcard','Why is dexamethasone used for preterm labour acceleration of fetal lung maturity?','["Antenatal dexamethasone (2 doses of 12 mg IM, 24 hours apart) crosses the placenta and induces surfactant production in fetal type II pneumocytes by activating glucocorticoid-responsive genes (SP-A, SP-B, SP-C surfactant protein genes). Reduces RDS (respiratory distress syndrome) risk by 40-60% in preterm infants < 34 weeks."]','A','Dexamethasone is preferred (vs betamethasone): crosses placenta well, negligible mineralocorticoid activity, long duration. Optimal effect if delivery occurs 24 hours - 7 days after first dose. Maternal side effects: transient hyperglycaemia (significant in diabetic mothers requiring insulin adjustment). Repeat courses no longer recommended (adverse neonatal brain effects).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','medium','flashcard','Describe avascular necrosis (osteonecrosis) of the femoral head as a corticosteroid complication.','["Mechanism: Glucocorticoids → fat cell hypertrophy in bone marrow → increased intraosseous pressure → impaired blood supply to femoral head → ischaemic necrosis. Risk: Higher with high doses (>20 mg prednisolone/day) and IV pulse therapy. Symptoms: Hip/groin pain worsening with weight-bearing. Diagnosis: MRI (most sensitive)."]','A','Avascular necrosis is more common in SLE patients on high-dose steroids. It is irreversible; treatment is joint preservation (bisphosphonates may slow progression) or total hip replacement. The femoral head is most commonly affected; can also occur in the knee, shoulder, and ankle. Bilateral in 50% of cases. Early MRI is essential as X-ray is normal in early stages.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Corticosteroid Pharmacology','easy','flashcard','What is the mechanism and clinical use of topical corticosteroids?','["Topical corticosteroids bind skin glucocorticoid receptors, suppressing PLA2 and inflammatory mediator production, reducing itch, erythema, and scaling. UK potency classes: Mild (hydrocortisone 1%), Moderate (clobetasone 0.05%), Potent (betamethasone 0.1%), Very potent (clobetasol 0.05%). Side effects: skin atrophy, telangiectasia, striae, perioral dermatitis."]','A','Use weakest effective potency for shortest duration. Face and flexures: mild/moderate only (thin, absorptive skin). Very potent steroids are contraindicated on the face. One fingertip unit (FTU ~0.5g) covers two adult palms. Tachyphylaxis (reduced responsiveness) can develop; intermittent use strategies (weekday dosing) reduce this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','easy','flashcard','What are the main types of oestrogen used in HRT and what is the difference between conjugated equine oestrogens (CEE) and oestradiol?','["CEE (Premarin): extracted from pregnant mare urine; mixture of oestrone sulphate, equilin sulphate, etc. — oral only. 17-beta-Oestradiol (Estradot, Sandrena, Femoston): bioidentical human oestrogen; oral or transdermal. Transdermal oestradiol: lower VTE risk due to bypass of hepatic first-pass metabolism."]','A','CEE was used in the WHI trial showing VTE and breast cancer risks. Transdermal oestradiol has a more physiological oestradiol:oestrone ratio and avoids hepatic first-pass effects on coagulation factors. The ESTHER study showed no significant VTE increase with transdermal oestradiol vs ~4-fold increase with oral oestrogen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','medium','flashcard','Compare the progestogens used in combined HRT: micronised progesterone vs medroxyprogesterone acetate (MPA) vs levonorgestrel.','["MPA (synthetic progestogen): Associated with increased breast cancer risk (WHI). Progesterone-only type preparation. Micronised progesterone (Utrogestan): Bioidentical; lower breast cancer risk (E3N study), fewer metabolic effects, can be taken orally or vaginally. Levonorgestrel (Mirena IUS): Localised uterine progestogen delivery; minimal systemic absorption; effective endometrial protection."]','A','The choice of progestogen influences breast cancer risk in combined HRT. E3N French cohort showed micronised progesterone had lower breast cancer risk than synthetic progestogens. Levonorgestrel IUS provides local endometrial protection with negligible systemic levels, allowing oral or transdermal oestradiol without separate oral progestogen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','medium','flashcard','What are the absolute contraindications to combined oestrogen-containing HRT?','["Absolute contraindications: (1) Oestrogen-dependent cancer (breast, endometrial, ovarian). (2) Unexplained vaginal bleeding. (3) Active VTE or high VTE risk (including thrombophilias). (4) Acute liver disease. (5) Recent cardiovascular event (MI, stroke). (6) Pregnancy. Relative: migraine with aura (increased stroke risk), uncontrolled hypertension."]','A','Prior breast cancer is an absolute contraindication to systemic HRT (may be discussed with specialist for severe menopausal symptoms). Women who have had oestrogen-receptor positive breast cancer should not use HRT without oncologist input. Topical vaginal oestrogen at low doses is generally safe even in breast cancer survivors for urogenital symptoms (minimal systemic absorption).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','hard','flashcard','How do SERMs (selective oestrogen receptor modulators) achieve tissue-specific agonism/antagonism?','["SERMs bind ERalpha and ERbeta with different affinities. The ligand induces different conformational changes in the ligand-binding domain (LBD) vs oestradiol. Different conformations recruit different co-activator (SRC-1, GRIP-1) or co-repressor (NCoR, SMRT) proteins. Agonist in bone (ERalpha dominant, co-activators recruited) vs antagonist in breast (ERalpha, co-repressors recruited)."]','A','Tamoxifen: ER antagonist in breast (treats ER+ breast cancer) but ER agonist in uterus (endometrial cancer risk) and bone (protects BMD). Raloxifene: antagonist in breast AND uterus (no endometrial cancer risk), agonist in bone. Bazedoxifene (paired with CE in Duavive): agonist in bone, antagonist in breast and uterus — used as the progestogen component in an alternative HRT combination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','easy','flashcard','What are the benefits of testosterone replacement therapy in hypogonadal men?','["Improvements in: libido and sexual function, energy and mood, muscle mass and strength, bone mineral density (reduced osteoporosis risk), erythropoiesis (corrects anaemia of hypogonadism), and insulin sensitivity (metabolic benefits). May improve glycaemic control in T2DM with hypogonadism."]','A','Monitoring on testosterone therapy: haematocrit (polycythaemia if > 54%), PSA (prostate), liver function (oral testosterone — not needed for IM/transdermal), blood pressure. Testosterone should be titrated to mid-normal range for age. Exogenous testosterone suppresses endogenous LH and FSH → infertility (irreversible without stopping therapy or using gonadotrophins).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','medium','flashcard','What are the risks of combined HRT identified in the Womens Health Initiative (WHI) trial?','["WHI (combined HRT — CEE + MPA vs placebo, mean 5.2 years): Increased risk: Breast cancer (HR 1.26), VTE (HR 2.06), stroke (HR 1.41). Decreased risk: Colorectal cancer (HR 0.63), hip fracture (HR 0.66). Coronary heart disease: slight increase in older women > 60, neutral/benefit if started within 10 years of menopause (timing hypothesis)."]','A','WHI was criticised for studying older women (average age 63), many with pre-existing CV disease, using oral oestrogen (highest VTE risk route), and synthetic MPA. Re-analysis and subsequent studies suggest younger (<60, within 10 years menopause), healthy women using transdermal oestradiol + micronised progesterone have a much more favourable benefit:risk profile.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','hard','flashcard','Describe the mechanism of tamoxifen in breast cancer treatment and its endometrial cancer risk.','["Tamoxifen: SERM. Mechanism: Competitive ER antagonist in breast (blocks oestradiol binding → reduces ER+ breast cancer proliferation). ALSO acts as ER AGONIST in uterus → promotes endometrial proliferation. Risk: 2-3-fold increased endometrial cancer risk (mainly endometrial adenocarcinoma). Annual gynaecological review; endometrial biopsy if postmenopausal bleeding."]','A','Tamoxifen is used for 5-10 years as adjuvant therapy in ER+ breast cancer (reduces recurrence by ~50%). The endometrial agonist effect means annual gynaecological surveillance and early investigation of any postmenopausal bleeding. Aromatase inhibitors (anastrozole, letrozole) are preferred in postmenopausal women — they lack endometrial agonism but cause more bone loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','easy','flashcard','What is testosterone replacement therapy in female-to-male (FtM) gender-affirming care and what effects does it produce?','["Testosterone (IM enanthate/cypionate or transdermal gel): masculinising effects include voice deepening (irreversible), clitoral growth, facial and body hair, increased muscle mass, fat redistribution (android pattern), cessation of menses, acne, and potential male-pattern baldness. Dose titrated to upper normal male range (testosterone 10-35 nmol/L)."]','A','Monitoring FtM testosterone therapy: testosterone levels (titrate to male range), haematocrit (polycythaemia risk), lipid profile, blood pressure, LFTs (oral testosterone only). Fertility: testosterone suppresses ovulation but is NOT reliable contraception — unintended pregnancy is possible. Fertility preservation (egg freezing) should be discussed before starting.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','medium','flashcard','What is the mechanism and use of ulipristal acetate as emergency contraception?','["Ulipristal acetate (ellaOne): Selective progesterone receptor modulator. Mechanism: Inhibits or delays ovulation by preventing the LH surge. Can work even after LH surge has started (unlike levonorgestrel). Effective up to 120 hours (5 days) post-unprotected sex. More effective than levonorgestrel EC, especially if taken 72-120 hours post-coitus."]','A','Ulipristal should NOT be taken with levonorgestrel concurrently (progesterone receptor competition reduces efficacy of both). Avoid in asthma patients using progesterone receptor modulators. Breastfeeding should be avoided for 1 week after use. The copper IUD is the most effective emergency contraception (>99% effective up to 5 days).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Sex Hormones & HRT','easy','flashcard','What are the non-contraceptive benefits of the combined oral contraceptive pill (COCP)?','["Benefits: (1) Reduced dysmenorrhoea and menorrhagia, (2) Reduced ovarian cancer risk (~40% per 5 years of use), (3) Reduced endometrial cancer risk (~50%), (4) Acne improvement (anti-androgenic progestogens: cyproterone, drospirenone), (5) Endometriosis and PCOS symptom control, (6) Reduced iron-deficiency anaemia from lighter periods."]','A','The ovarian and endometrial cancer protection persists for >15 years after stopping. These cancer-protective benefits must be weighed against small increased VTE and breast cancer risks. The COCP also protects against ectopic pregnancy, benign breast disease, and ovarian cysts. The LNG-IUS (Mirena) is preferred for heavy menstrual bleeding where contraception is not the primary goal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','easy','flashcard','How does orlistat work and what are its GI side effects?','["Orlistat inhibits gastric and pancreatic lipase enzymes in the GI lumen, preventing hydrolysis of dietary triglycerides → reduces fat absorption by ~30%. GI side effects (dose-related, worsen with high-fat meals): oily/fatty stools (steatorrhoea), faecal urgency/incontinence, oily spotting, flatulence with discharge. These are self-limiting if diet is low-fat."]','A','Fat-soluble vitamins (A, D, E, K) are incompletely absorbed on orlistat due to impaired fat absorption. A daily fat-soluble vitamin supplement taken 2 hours before or after orlistat is recommended. Orlistat is also used as a treatment for type 2 diabetes (modest HbA1c reduction) and may reduce progression from pre-diabetes to diabetes (XENDOS trial: 37% risk reduction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','medium','flashcard','Compare GLP-1 agonists approved for obesity: liraglutide 3.0 mg (Saxenda) vs semaglutide 2.4 mg (Wegovy).','["Liraglutide 3.0 mg: Daily SC injection, mean weight loss ~5-7% (SCALE trial), dose escalated over 5 weeks. Semaglutide 2.4 mg: Once-weekly SC injection, mean weight loss ~15% (STEP 1), dose escalated over 16 weeks. SELECT trial: semaglutide 2.4 mg reduced MACE by 20% in non-diabetic obese patients with established CV disease."]','A','Semaglutide 2.4 mg represents a transformative advance, with weight loss approaching that achievable with bariatric surgery (25-30%) in some patients. The once-weekly injection improves adherence vs daily liraglutide. Both have the same black-box warning for MTC and are contraindicated in MEN2. Both require dose escalation to minimise GI side effects (nausea, vomiting).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','medium','flashcard','What is the mechanism and clinical evidence for naltrexone/bupropion (Mysimba) in obesity?','["Bupropion: activates POMC neurons (increases alpha-MSH → MC4R → satiety). Naltrexone: blocks opioid auto-inhibition of POMC neurons → enhances bupropion effect. COR trials: mean weight loss 5-8% beyond lifestyle. Additional benefit: reduces binge-eating behaviour (mesolimbic dopamine/opioid pathway action). Contraindicated in: opioid use, seizure history, uncontrolled hypertension."]','A','Naltrexone/bupropion is particularly useful for patients with eating disorder components to their obesity. Bupropions dopaminergic effects also improve mood and reduce depressive symptoms that may contribute to obesity. The FDA required post-marketing cardiovascular outcome data (LIGHT trial), which showed no CV harm. Not recommended with MAOIs or linezolid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','hard','flashcard','Describe the mechanism of tirzepatide as a dual GIP/GLP-1 agonist and its advantages over GLP-1 agonists alone.','["Tirzepatide (twincretin): Single peptide activating both GIP receptor (GIPR) and GLP-1R. GLP-1R activation: Insulin secretion, glucagon suppression, gastric emptying delay, satiety. GIPR activation: Enhanced insulin secretion (synergises with GLP-1), adipocyte lipolysis promotion, reduced adipose inflammation, direct hypothalamic appetite suppression. Result: ~20% weight loss (vs ~15% semaglutide)."]','A','The GIP receptor was previously thought to be obesogenic (GIP drives fat storage). However, GIP AGONISM in the context of GLP-1 co-activation appears to synergistically enhance weight loss — possibly by upregulating GLP-1R sensitivity. SURMOUNT-1 (non-diabetic obesity): 15 mg tirzepatide → 20.9% weight loss. SURPASS-2 (T2DM): superior HbA1c and weight reduction vs semaglutide 1 mg (diabetes dose).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','easy','flashcard','What are the eligibility criteria for pharmacological obesity treatment in the UK/NICE?','["NICE criteria for pharmacological obesity treatment (e.g., orlistat): BMI ≥ 30 kg/m2 (or ≥ 27 with T2DM, hypertension, dyslipidaemia, or sleep apnoea). Must have made serious attempt to lose weight through diet/exercise first. GLP-1 agonists (semaglutide 2.4 mg - NICE approved 2023): BMI ≥ 35 with weight-related comorbidity (or ≥ 30 in certain specialist settings)."]','A','UK eligibility for tirzepatide (Mounjaro) as approved by NICE (2024): BMI ≥ 35 with type 2 diabetes OR ≥ 30 with T2DM in specialist weight management services. For obesity without T2DM, semaglutide 2.4 mg or liraglutide 3.0 mg are the current NICE-approved GLP-1 options. Bariatric surgery remains gold standard for severe obesity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','medium','flashcard','Why must fat-soluble vitamins be supplemented during orlistat therapy?','["Orlistat inhibits fat absorption. Fat-soluble vitamins (A, D, E, K and beta-carotene) require dietary fat for micellar solubilisation and absorption via chylomicrons. Blocking fat absorption proportionally reduces vitamin absorption. A daily multivitamin supplement containing A, D, E, K should be taken at least 2 hours before or after orlistat to avoid chelation with unabsorbed drug."]','A','Vitamin D deficiency is particularly important to prevent given the obesity-osteoporosis overlap: obese patients commonly have low vitamin D, and further reducing absorption worsens this. Vitamin K deficiency can interact with warfarin anticoagulation (patients on warfarin need increased INR monitoring when starting orlistat). Vitamin A deficiency may cause night blindness with prolonged orlistat use without supplementation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','hard','flashcard','Describe the cardiovascular outcome data for obesity pharmacotherapy (SELECT trial for semaglutide).','["SELECT trial (2023): N=17,604, adults with obesity (BMI ≥27) and established CVD, NO T2DM, randomised to semaglutide 2.4 mg weekly vs placebo for 5 years. Primary endpoint: 3-point MACE (CV death, non-fatal MI, non-fatal stroke). Result: 20% relative risk reduction (HR 0.80, p<0.001). Mean weight loss: 9.4% vs 0.9%. First obesity drug (non-diabetic) to show CV benefit."]','A','SELECT changed obesity from a cosmetic concern to a cardiovascular disease in its own right. The CV benefit appeared independent of weight loss magnitude (consistent across weight-loss tertiles) and emerged within the first year. Mechanisms proposed: anti-inflammatory effects, improved cardiac remodelling, reduced visceral adiposity. The trial enrolled only patients with established CVD; primary prevention data are awaited.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','easy','flashcard','What are the contraindications to GLP-1 agonist therapy for obesity?','["Absolute contraindications: Personal or family history of medullary thyroid carcinoma (MTC), Multiple Endocrine Neoplasia type 2 (MEN2), history of pancreatitis (caution), type 1 diabetes. Relative/caution: Gastroparesis (gastric emptying already impaired), severe renal impairment (exenatide), inflammatory bowel disease."]','A','Patients should be counselled about the medullary thyroid carcinoma black-box warning (FDA, based on rodent data; human causality unproven) and the pancreatitis risk. GLP-1 agonists for obesity should be prescribed as adjunct to reduced-calorie diet and physical activity. Weight regain occurs when treatment is stopped (chronic disease model — ongoing treatment needed).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','medium','flashcard','What is the role of pharmacotherapy vs bariatric surgery in severe obesity and which patients should be referred for surgery?','["Pharmacotherapy: BMI 27-40 with comorbidities; lifestyle modification has failed; bridge to surgery; patients declining surgery. Bariatric surgery: BMI ≥40 (or ≥35 with comorbidities); more effective (25-35% weight loss); more durable. Refer when: BMI ≥40, or ≥35 with T2DM (remission rate 50-80%), hypertension, OSA, or other weight-related comorbidities, and patient is fit for surgery."]','A','Bariatric surgery achieves mean weight loss of 25-35% (vs ~15-20% with best pharmacotherapy). T2DM remission in 50-80% post-sleeve gastrectomy/Roux-en-Y gastric bypass — likely through GLP-1 surge post-bypass (Foregut hypothesis) and caloric restriction. Pre-operative pharmacotherapy can reduce surgical risk by reducing liver volume (fatty liver) and metabolic comorbidities.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Endocrinology','Pharmacology','Drugs for Obesity','hard','flashcard','Why does weight regain occur after stopping GLP-1 agonist therapy and what does this mean for obesity management?','["Mechanism of weight regain: GLP-1 receptor agonist withdrawal removes central appetite-suppressing signal. Hypothalamic set-point reverts. Adipocyte lipolysis capacity reduced by treatment (smaller adipocytes). STEP 4 trial: semaglutide withdrawal resulted in regain of ~2/3 of lost weight within 1 year (from ~17% to ~5% net loss maintained at 1 year off drug)."]','A','Obesity is a chronic relapsing disease requiring long-term treatment, analogous to hypertension or diabetes. Stopping pharmacotherapy should be planned with transition to sustainable strategies. Bariatric surgery provides more durable weight loss (~25-35% maintained long-term). Combination therapy (GLP-1 agonist + lifestyle intensification) improves maintenance. The concept of obesity as a set-point disorder requiring ongoing pharmacological suppression is now established.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
